create function alm_private.parse_birth_date(p_value text) returns date language plpgsql stable security invoker set search_path='' as $$
declare d date;begin
 if p_value is null or p_value!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'AGE_INVALID';end if;
 begin d:=p_value::date;exception when invalid_datetime_format or datetime_field_overflow then raise exception 'AGE_INVALID';end;
 if to_char(d,'YYYY-MM-DD')<>p_value or d<'1900-01-01' or d>current_date then raise exception 'AGE_INVALID';end if;
 return d;
end;$$;
create function alm_private.capture_age_declaration() returns trigger language plpgsql security definer set search_path='' as $$
declare m jsonb:=coalesce(to_jsonb(new)->'raw_user_meta_data','{}');begin
 -- Old clients remain usable, but an unknown age never enables adult content.
 if m ? 'alm_birth_date' or m ? 'alm_age_attested' then
  if m->'alm_age_attested' is distinct from 'true'::jsonb then raise exception 'AGE_INVALID';end if;
  insert into alm_private.account_age(user_id,birth_date) values(new.id,alm_private.parse_birth_date(m->>'alm_birth_date'));
 end if;
 return new;
end;$$;
create trigger alm_capture_age_declaration after insert on auth.users for each row execute function alm_private.capture_age_declaration();
create function alm_private.adult_sharing(p_user uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from alm_private.account_age a where a.user_id=p_user and extract(year from age(current_date,a.birth_date))>=18 and not a.exclude_adult);
$$;
create function alm_private.account_age_state() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare u uuid:=alm_private.require_actor();a alm_private.account_age;adult boolean;begin
 select * into a from alm_private.account_age where user_id=u;
 if not found then return jsonb_build_object('recorded',false,'adult',false,'excludeAdult',true);end if;
 adult:=extract(year from age(current_date,a.birth_date))>=18;
 return jsonb_build_object('recorded',true,'adult',adult,'excludeAdult',not adult or a.exclude_adult);
end;$$;
create function alm_private.set_account_age(p_birth_date text,p_attested boolean,p_exclude_adult boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=alm_private.require_actor();a alm_private.account_age;d date;begin
 perform pg_advisory_xact_lock(hashtext(u::text));select * into a from alm_private.account_age where user_id=u for update;
 if not found then
  if p_attested is distinct from true then raise exception 'AGE_INVALID';end if;
  d:=alm_private.parse_birth_date(p_birth_date);
  insert into alm_private.account_age(user_id,birth_date) values(u,d);
 else
  d:=a.birth_date;
  if p_birth_date is not null and alm_private.parse_birth_date(p_birth_date)<>d then raise exception 'AGE_LOCKED';end if;
 end if;
 update alm_private.account_age set exclude_adult=case when extract(year from age(current_date,d))>=18 then coalesce(p_exclude_adult,true) else true end where user_id=u;
 return alm_private.account_age_state();
end;$$;
create function public.alm_account_age_state() returns jsonb language sql stable security invoker set search_path='' as $$select alm_private.account_age_state()$$;
create function public.alm_set_account_age(p_birth_date text default null,p_attested boolean default false,p_exclude_adult boolean default true) returns jsonb language sql security invoker set search_path='' as $$select alm_private.set_account_age(p_birth_date,p_attested,p_exclude_adult)$$;

create function alm_private.content_adult(p_item jsonb) returns boolean language sql stable security definer set search_path='' as $$
 select case when coalesce(p_item->>'mal_id','')~'^[1-9][0-9]{0,8}$' then exists(select 1 from alm_private.community_content_adult where mal_id=(p_item->>'mal_id')::integer) else false end;
$$;
create function alm_private.content_can_read(p_owner uuid,p_item jsonb) returns boolean language sql stable security definer set search_path='' as $$
 select alm_private.active_actor() is not null and (alm_private.content_item_allowed(p_item) or alm_private.content_adult(p_item) and alm_private.adult_sharing(p_owner) and alm_private.adult_sharing(auth.uid()));
$$;
alter policy library_read on public.alm_library using(
 alm_private.content_can_read(owner_id,jsonb_build_object('mal_id',mal_id,'genres',genres)) and
 (alm_private.can_view(owner_id,'library') or favorite and alm_private.can_view(owner_id,'favorites') or status='Watching' and alm_private.can_view(owner_id,'watching') or alm_private.showcase(owner_id,mal_id)));
alter policy recommendations_read on public.alm_recommendations using(
 alm_private.active_actor() in(sender,recipient) and alm_private.content_can_read(sender,anime) and
 (alm_private.content_item_allowed(anime) or alm_private.content_can_read(recipient,anime)));

create or replace function alm_private.publish_profile(p_profile jsonb,p_items jsonb,p_dna jsonb,p_activity jsonb) returns void language plpgsql security definer set search_path='' as $$
declare u uuid:=alm_private.require_actor();filtered jsonb;clean_profile jsonb;safe_dna jsonb;adult boolean;begin
 perform pg_advisory_xact_lock(hashtext(u::text));adult:=alm_private.adult_sharing(u);
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>20000 or pg_column_size(p_items)>8000000 then raise exception 'PAYLOAD_LIMIT';end if;
 select coalesce(jsonb_agg(i),'[]') into filtered from jsonb_array_elements(p_items) i where alm_private.content_item_allowed(i) or adult and alm_private.content_adult(i);
 -- Featured IDs and cross-profile aggregates remain safe for every viewer.
 clean_profile:=p_profile||jsonb_build_object('featured',coalesce((select jsonb_agg(id) from jsonb_array_elements(coalesce(p_profile->'featured','[]')) id where id::text~'^[1-9][0-9]{0,8}$' and alm_private.content_allowed((id::text)::integer)),'[]'));
 perform alm_private.publish_before_content_v66(clean_profile,filtered,'[]',p_activity);
 select coalesce(jsonb_agg(jsonb_build_object('genre',genre,'count',n)),'[]') into safe_dna from
 (select g as genre,count(*) as n from public.alm_library l cross join unnest(l.genres) g where l.owner_id=u and l.status in('Watching','Completed') and alm_private.content_item_allowed(jsonb_build_object('mal_id',l.mal_id,'genres',l.genres)) group by g order by count(*) desc,g limit 12) q;
 update public.alm_dna set data=safe_dna where owner_id=u;
end;$$;
create or replace function alm_private.recommend(p_recipient uuid,p_anime jsonb,p_message text) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=alm_private.require_actor();begin
 if not (alm_private.content_item_allowed(p_anime) or alm_private.content_adult(p_anime) and alm_private.adult_sharing(u) and alm_private.adult_sharing(p_recipient)) then raise exception 'CONTENT_NOT_SHARED';end if;
 return alm_private.recommend_before_content_v66(p_recipient,p_anime,p_message);
end;$$;
revoke all on function alm_private.parse_birth_date(text),alm_private.capture_age_declaration(),alm_private.adult_sharing(uuid),alm_private.content_adult(jsonb) from public,anon,authenticated;
revoke all on function alm_private.account_age_state(),alm_private.set_account_age(text,boolean,boolean),alm_private.content_can_read(uuid,jsonb),public.alm_account_age_state(),public.alm_set_account_age(text,boolean,boolean) from public,anon;
grant execute on function alm_private.account_age_state(),alm_private.set_account_age(text,boolean,boolean),alm_private.content_can_read(uuid,jsonb),public.alm_account_age_state(),public.alm_set_account_age(text,boolean,boolean) to authenticated;
commit;
